def lcs(s1, s2): 
    # initializing lcs[i][j] to -inf
    lcs = [[-float('inf') for j in range(len(s2))] for i in range(len(s1))]

    # scanning s1
    for i in range(len(s1)):
        for j in range(len(s2)):
            # update lcs[i][j] 
            if (s1[i] == s2[j]):
                lcs[i][j] = max(lcs[i+1][j-1] + 1, lcs[i][j-1])
                # update lcs[i+1]
                if (i+1 < len(s1) and s1[i+1] == s2[j]):
                    lcs[i+1][j] = max(lcs[i+1][j-1] + 1, lcs[i+1][0])

    # return lcs[len(s1)-len(s2)+1][len(s2)]
    return max(lcs[len(s1)-len(s2)+1][len(s2):])

